import json
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def excel_serial_to_date(serial):
    """Convert Excel serial number to YYYY-MM-DD string."""
    if serial == "":
        return None
    try:
        # Excel's epoch is 1899-12-30 (with leap year bug we ignore for modern dates)
        base = datetime(1899, 12, 30)
        days = int(float(serial))
        date = base + timedelta(days=days)
        return date.strftime("%Y-%m-%d")
    except (ValueError, TypeError):
        return None

def read_lca_disclosure(packet_dir):
    """Read lca_disclosure.csv and return dict keyed by CASE_NUMBER."""
    path = Path(packet_dir) / "lca_disclosure.csv"
    if not path.exists():
        return {}

    data = {}
    with open(path, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    if not lines:
        return data

    headers = [h.strip() for h in lines[0].strip().split(',')]
    for line in lines[1:]:
        parts = [p.strip() for p in line.strip().split(',')]
        if len(parts) != len(headers):
            continue
        record = dict(zip(headers, parts))
        case_num = record.get('CASE_NUMBER')
        if case_num:
            data[case_num] = record
    return data

def extract_wage_facts(record):
    """Extract offered wage and prevailing wage from lca_disclosure record."""
    offered = record.get('WAGE_RATE_OF_PAY_FROM', '').strip()
    prevailing = record.get('PREVAILING_WAGE', '').strip()

    # Convert to decimal string if present
    offered_val = None
    if offered and offered != '':
        try:
            offered_val = str(float(offered))
        except ValueError:
            offered_val = None

    prevailing_val = None
    if prevailing and prevailing != '':
        try:
            prevailing_val = str(float(prevailing))
        except ValueError:
            prevailing_val = None

    return offered_val, prevailing_val

def extract_date_facts(record):
    """Extract begin and end dates from lca_disclosure record."""
    begin_serial = record.get('BEGIN_DATE', '').strip()
    end_serial = record.get('END_DATE', '').strip()

    begin_date = excel_serial_to_date(begin_serial) if begin_serial else None
    end_date = excel_serial_to_date(end_serial) if end_serial else None

    return begin_date, end_date

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    # Read data
    lca_data = read_lca_disclosure(packet_dir)

    # Prepare result
    result = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        result[pair] = {}

        if rule_id not in facts_by_rule:
            continue

        record = lca_data.get(entity)

        for fact_name in facts_by_rule[rule_id]:
            if rule_id == "lca.wage_105":
                if fact_name == "offered wage":
                    if not record:
                        result[pair][fact_name] = "ABSENT"
                    else:
                        offered, _ = extract_wage_facts(record)
                        if offered is None:
                            result[pair][fact_name] = "ABSENT"
                        else:
                            result[pair][fact_name] = [offered, "lca_disclosure"]
                elif fact_name == "prevailing wage":
                    if not record:
                        result[pair][fact_name] = "ABSENT"
                    else:
                        _, prevailing = extract_wage_facts(record)
                        if prevailing is None:
                            result[pair][fact_name] = "ABSENT"
                        else:
                            result[pair][fact_name] = [prevailing, "lca_disclosure"]

            elif rule_id == "lca.three_years":
                if fact_name == "begin date":
                    if not record:
                        result[pair][fact_name] = "ABSENT"
                    else:
                        begin, _ = extract_date_facts(record)
                        if begin is None:
                            result[pair][fact_name] = "ABSENT"
                        else:
                            result[pair][fact_name] = [begin, "lca_disclosure"]
                elif fact_name == "end date":
                    if not record:
                        result[pair][fact_name] = "ABSENT"
                    else:
                        _, end = extract_date_facts(record)
                        if end is None:
                            result[pair][fact_name] = "ABSENT"
                        else:
                            result[pair][fact_name] = [end, "lca_disclosure"]

    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

