import json
import csv
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def read_csv_file(packet_dir, filename):
    """Read CSV file and return list of dicts."""
    filepath = os.path.join(packet_dir, filename)
    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        return list(reader)

def excel_date_to_iso(excel_date_str):
    """Convert Excel serial date to ISO format YYYY-MM-DD."""
    if not excel_date_str:
        return None
    try:
        # Excel date is days since 1899-12-30 (with 1900 leap year bug)
        # Python's datetime starts from 1899-12-30
        base_date = datetime(1899, 12, 30)
        days = int(float(excel_date_str))
        result_date = base_date + timedelta(days=days)
        return result_date.strftime('%Y-%m-%d')
    except (ValueError, TypeError):
        return None

def process_packet(packet_dir, manifest_file):
    with open(manifest_file, 'r') as f:
        manifest = json.load(f)

    # Read the LCA disclosure file
    lca_data = {}
    csv_filename = "lca_disclosure.csv"
    csv_path = os.path.join(packet_dir, csv_filename)

    if os.path.exists(csv_path):
        rows = read_csv_file(packet_dir, csv_filename)
        for row in rows:
            case_num = row.get('CASE_NUMBER')
            if case_num:
                lca_data[case_num] = row

    # Initialize result structure
    result = {}

    # Process each pair
    for pair in manifest['pairs']:
        rule_id, entity = pair.split('::', 1)
        result[pair] = {}

        # Get facts for this rule
        facts = manifest['facts'][rule_id]

        for fact in facts:
            if rule_id == 'lca.wage_105':
                if fact == 'offered wage':
                    if entity in lca_data:
                        wage_from = lca_data[entity].get('WAGE_RATE_OF_PAY_FROM')
                        if wage_from and wage_from.strip():
                            # Remove commas and convert to decimal string
                            wage_clean = wage_from.replace(',', '').strip()
                            try:
