                                float(wage_clean)
                                result[pair][fact] = [wage_clean, "lca_disclosure"]
                            except ValueError:
                                result[pair][fact] = "ABSENT"
                        else:
                            result[pair][fact] = "ABSENT"
                    else:
                        result[pair][fact] = "ABSENT"

                elif fact == 'prevailing wage':
                    if entity in lca_data:
                        pw = lca_data[entity].get('PREVAILING_WAGE')
                        if pw and pw.strip():
                            # Remove commas and convert to decimal string
                            pw_clean = pw.replace(',', '').strip()
                            try:
                                float(pw_clean)
                                result[pair][fact] = [pw_clean, "lca_disclosure"]
                            except ValueError:
                                result[pair][fact] = "ABSENT"
                        else:
                            result[pair][fact] = "ABSENT"
                    else:
                        result[pair][fact] = "ABSENT"

            elif rule_id == 'lca.three_years':
                if fact == 'begin date':
                    if entity in lca_data:
                        begin_date = lca_data[entity].get('BEGIN_DATE')
                        iso_date = excel_date_to_iso(begin_date)
                        if iso_date:
                            result[pair][fact] = [iso_date, "lca_disclosure"]
                        else:
                            result[pair][fact] = "ABSENT"
                    else:
                        result[pair][fact] = "ABSENT"

