        rule_id, entity = pair.split('::', 1)
        if entity not in entity_to_rule:
            entity_to_rule[entity] = {}
        entity_to_rule[entity][rule_id] = pair

    # For each entity, check if same fact has different values across rules
    # (though in this manifest, each rule has different facts)
    # Actually, in this specific case, conflicts aren't possible since
